// The beginner's lesson as a learner meets it, pinned BEFORE the method registry replaced the rung ladder
// (ADR 0011, dev-docs/solve-methods-plan.md Phase 1).
//
// `method-steps.json` is not this: its `beginner` entry calls `methodFor(rungs)`, which is the APP's
// last-layer route, and it records the solver's steps without their holds. What a child on the default
// install is shown is `lessonFor` on the course's route — the steps as converted into the scan frame, the
// hold each move is made in, the caption each step says, the cues it lights, the sections the move list
// is cut into and which step each move belongs to. That whole record is what is frozen here, because the
// refactor that moved the method into a registry is claimed to change none of it.
//
// Regenerate ONLY to record a deliberate change to what the beginner is taught, and say so in the commit:
//
//   node test/fixtures/regen-beginner-lesson.mjs

import Cube from '../../vendor/cubejs.js';
import { CONTRACT_CUBES } from './solver-cubes.mjs';
import { seededScrambles } from './seeded-scrambles.mjs';

export const SEED = 20260908;
export const COUNT = 12;

const SOLVED = 'UUUUUUUUURRRRRRRRRFFFFFFFFFDDDDDDDDDLLLLLLLLLBBBBBBBBB';

/** The cubes, in the scan frame: the twelve seeded scrambles `method-steps.json` uses, then the four
 *  frozen contract cubes. */
export function baselineCubes() {
  const scrambled = seededScrambles(COUNT, SEED).map((alg) => {
    const c = Cube.fromString(SOLVED);
    c.move(alg);
    return c.asString();
  });
  return [...scrambled, ...CONTRACT_CUBES];
}

/** One lesson as the learner-facing fields. `whyText` is passed in so the caption is the one the screen
 *  renders, not the key it is looked up by. */
export function lessonRecord(lesson, whyText) {
  return {
    alg: lesson.alg,
    moves: [...lesson.moves],
    moveHolds: lesson.moveHolds.map((h) => [...h]),
    stepFacelets: [...lesson.stepFacelets],
    moveStep: [...lesson.moveStep],
    sections: lesson.sections.map((s) => ({ ...s })),
    steps: lesson.steps.map((s) => ({
      stage: s.stage,
      kind: s.kind,
      alg: s.alg,
      hold: [...s.hold],
      ...(s.caseName === undefined ? {} : { caseName: s.caseName }),
      why: s.why,
      caption: whyText(s),
      highlight: s.highlight,
    })),
  };
}

export const COMMENT =
  'Generated by test/fixtures/regen-beginner-lesson.mjs: the beginner\'s lesson (rung 0, the course\'s last ' +
  'layer) as lessonFor built it before ADR 0011. Never hand-edited.';

/**
 * The booted app's `lessonFor` and `whyText`, with the settings a new install has. Booted the way
 * `cube-subject.test.mjs` boots it — happy-dom, the real `index.html`, and a wait for the solver — because
 * `lessonFor` is the app's own function and a copy of its pipeline here would pin the copy, not the app.
 */
export async function bootLesson() {
  const { readFileSync } = await import('node:fs');
  const { Window } = await import('happy-dom');
  const html = readFileSync(new URL('../../index.html', import.meta.url), 'utf8');
  const win = new Window({
    url: 'http://localhost/#/timer',
    settings: {
      disableJavaScriptFileLoading: true, disableCSSFileLoading: true,
      disableComputedStyleRendering: true, fetch: { disableSameOriginPolicy: true },
    },
  });
  win.document.write(html);
  for (const k of [
    'window', 'document', 'navigator', 'location', 'history', 'localStorage', 'customElements',
    'HTMLElement', 'CustomEvent', 'requestAnimationFrame', 'cancelAnimationFrame', 'performance',
  ]) {
    Object.defineProperty(globalThis, k, { value: win[k], writable: true, configurable: true });
  }
  await import('../../lib/app.js');
  const svc = await import('../../lib/solver-service.js');
  const t0 = Date.now();
  while (!svc.solverReady && Date.now() - t0 < 60000) await new Promise((r) => setTimeout(r, 50));
  if (!svc.solverReady) throw new Error('beginner-lesson: the solver did not load within 60 s');
  const { lessonFor } = await import('../../lib/cube-subject.js');
  const { whyText } = await import('../../lib/method-lesson.js');
  return { lessonFor, whyText, win };
}
